const now = new Date().toISOString();
const runId = `ft_raw_${now.replace(/[-:.]/g, '').slice(0, 15)}Z`;
const day = now.slice(0, 10);
return [{ json: { run_id: runId, schema_version: 'g8n.workflow-envelope.v1', persistence_version: 'g8n.raw-ingestion-persistence.v1', source: 'france_travail', status: 'started', timestamps: { started_at: now, completed_at: null }, raw_root_path: `data/raw/france_travail/${day}/${runId}`, config: { config_version: 'g8n.france-travail.search.v1', input_config_hash: 'manual-input-config-hash-placeholder' }, checkpoint: { last_persisted_range: null, next_range: '0-49' }, counters: { pages_written: 0, offers_seen: 0, offers_upserted: 0, new: 0, unchanged: 0, updated: 0, errors: 0 }, page: { page_index: 0, range: '0-49', raw_page_path: `data/raw/france_travail/${day}/${runId}/page-0-0-49.json`, page_hash: null, offers: [] }, persistence_result: { file_written: false, hashes_computed: false, rows_upserted: false, run_updated: false }, errors: [] } }];

const input = $input.first().json;
const collectedAt = new Date().toISOString();
const offers = input.page.offers || [];
const rows = offers.map((offer, index) => {
  const sourceOfferId = String(offer.id || offer.source_offer_id || `missing-${index}`);
  const previous = offer.previous || null;
  const payloadHash = offer.payload_hash || 'sha256-placeholder-compute-locally';
  const payloadStatus = !previous ? 'new' : previous.payload_hash === payloadHash ? 'unchanged' : 'updated';
  return { raw_offer_key: `${input.source}:${sourceOfferId}`, run_id: input.run_id, source: input.source, source_offer_id: sourceOfferId, raw_path: `${input.page.raw_page_path}#offers/${index}`, raw_page_path: input.page.raw_page_path, source_page_range: input.page.range, page_index: input.page.page_index, payload_hash: payloadHash, collected_at: collectedAt, first_seen_at: previous?.first_seen_at || collectedAt, last_seen_at: collectedAt, payload_status: payloadStatus, source_updated_at: offer.dateActualisation || offer.updated_at || null };
});
const statusCounts = rows.reduce((acc, row) => ({ ...acc, [row.payload_status]: (acc[row.payload_status] || 0) + 1 }), { new: 0, unchanged: 0, updated: 0 });
return [{ json: { ...input, raw_job_offer_upserts: rows, counters: { ...input.counters, offers_seen: rows.length, new: statusCounts.new || 0, unchanged: statusCounts.unchanged || 0, updated: statusCounts.updated || 0 } } }];

const input = $input.first().json;
const persistenceSucceeded = input.persistence_result.file_written && input.persistence_result.hashes_computed && input.persistence_result.rows_upserted && input.persistence_result.run_updated;
const checkpoint = persistenceSucceeded ? { last_persisted_range: input.page.range, next_range: input.checkpoint.next_range } : input.checkpoint;
const status = persistenceSucceeded ? 'partial' : 'started';
const ingestionRunUpsert = { run_id: input.run_id, source: input.source, status, started_at: input.timestamps.started_at, completed_at: null, schema_version: input.schema_version, input_config_hash: input.config.input_config_hash, raw_root_path: input.raw_root_path, config_version: input.config.config_version, checkpoint_json: JSON.stringify(checkpoint), counters_json: JSON.stringify(input.counters), notes: persistenceSucceeded ? 'Page persisted; ready for next checkpoint.' : 'Skeleton refused checkpoint advancement until file/hash/Data Table steps are marked successful.' };
return [{ json: { ...input, status, checkpoint, ingestion_run_upsert: ingestionRunUpsert, checkpoint_advanced: persistenceSucceeded } }];
